<script setup lang="ts">
/**
 * Credits Widget
 *
 * Footer credit line: "Made by [Softmasters logo] · Running on [LessCMS logo]".
 * Element-group structure: text + logo + config (container style via settings).
 */

import { computed } from 'vue'
import { useLanguage } from '@/composables/useLanguage'
import type { CreditsWidgetData } from '@/types/widgets'

defineOptions({
  inheritAttrs: false
})

interface Props {
  data: CreditsWidgetData
  language?: string
  settings?: Record<string, any>
}

const props = defineProps<Props>()

const { extractValue } = useLanguage(props.language)

const textGroup = computed(() => props.data.text || {})
const logoGroup = computed(() => props.data.logo || {})
const configGroup = computed(() => props.data.config || {})

function resolveColorValue(val: string | null | undefined): string | null {
  if (!val) return null
  if (val.startsWith('var:')) {
    const parts = val.split(':')
    const code = parts[1]
    const opacity = parts.length >= 3 ? parseInt(parts[2]) : 100
    if (opacity < 100) {
      return `color-mix(in srgb, var(--lcms-color-${code}) ${opacity}%, transparent)`
    }
    return `var(--lcms-color-${code})`
  }
  if (val.startsWith('#') && val.includes(':')) {
    const parts = val.split(':')
    const hex = parts[0]
    const opacity = parseInt(parts[1])
    if (opacity < 100) {
      return `color-mix(in srgb, ${hex} ${opacity}%, transparent)`
    }
    return hex
  }
  return val
}

const madeByLabel = computed(() => extractValue(textGroup.value.made_by as any) || 'Made by')
const runningOnLabel = computed(() => extractValue(textGroup.value.running_on as any) || 'Running on')

const showMadeBy = computed(() => configGroup.value.show_made_by !== false)
const showRunningOn = computed(() => configGroup.value.show_running_on !== false)
const separator = computed(() => configGroup.value.separator || '')
const alignment = computed(() => configGroup.value.alignment || 'center')
const isStacked = computed(() => configGroup.value.layout === 'stacked')
const targetBlank = computed(() => configGroup.value.target_blank !== false)
const linkMadeBy = computed(() => configGroup.value.link_made_by || '')
const linkRunningOn = computed(() => configGroup.value.link_running_on || '')
const accent = computed(() => logoGroup.value.accent !== false)

const textColor = computed(() => resolveColorValue(textGroup.value.color))
const textSize = computed(() => textGroup.value.size ?? 13)
const logoColor = computed(() => resolveColorValue(logoGroup.value.color))
const logoHoverColor = computed(() => resolveColorValue(logoGroup.value['color:hover']))
const logoHeight = computed(() => logoGroup.value.height ?? 16)

const rootClasses = computed(() => [
  'lcms-credits',
  { 'lcms-credits--stacked': isStacked.value, 'lcms-credits--muted': !textColor.value }
])

const rootStyle = computed(() => {
  const style: Record<string, string> = {
    '--credits-size': `${textSize.value}px`,
    '--credits-logo-h': `${logoHeight.value}px`,
    '--credits-gap': separator.value ? '12px' : '28px',
    '--credits-justify': ({ left: 'flex-start', right: 'flex-end' } as Record<string, string>)[alignment.value] || 'center',
    '--credits-align-items': ({ left: 'flex-start', right: 'flex-end' } as Record<string, string>)[alignment.value] || 'center',
    '--credits-text-align': alignment.value
  }
  if (textColor.value) style['--credits-text-color'] = textColor.value
  if (logoColor.value) style['--credits-logo-color'] = logoColor.value
  if (logoHoverColor.value) style['--credits-logo-hover'] = logoHoverColor.value
  return style
})

const linkAttrs = (href: string) => ({
  href: href || undefined,
  target: href && targetBlank.value ? '_blank' : undefined,
  rel: href ? 'noopener' : undefined
})
</script>

